package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.net.*;
import java.util.*;

/** Startup-only operator configuration. Secret values never enter frozen executor descriptors. */
public final class AgentTransportConfig {
  public record HttpProfile(String submitUrl,String bearer,String keyId,String secret,int requestTimeoutMs,int maxResponseBytes) {}
  private final Map<String,ObjectNode> agents=new LinkedHashMap<>();private final Map<String,String> env;
  public final String callbackBaseUrl;public final int callbackMaxSkewSeconds,replayTtlMs,replayMaxEntries;
  public AgentTransportConfig(){this(System.getenv());}
  public AgentTransportConfig(Map<String,String> env){this.env=Map.copyOf(env);boolean insecure="true".equals(env.get("HTTP_AGENT_ALLOW_INSECURE"));callbackMaxSkewSeconds=positive(env.get("HTTP_AGENT_CALLBACK_MAX_SKEW_SECONDS"),300,"HTTP_AGENT_CALLBACK_MAX_SKEW_SECONDS");replayTtlMs=positive(env.get("HTTP_AGENT_REPLAY_TTL_MS"),callbackMaxSkewSeconds*1000,"HTTP_AGENT_REPLAY_TTL_MS");if((long)replayTtlMs<(long)callbackMaxSkewSeconds*1000)invalid("HTTP_AGENT_REPLAY_TTL_MS must cover the callback clock-skew window");replayMaxEntries=positive(env.get("HTTP_AGENT_REPLAY_MAX_ENTRIES"),10000,"HTTP_AGENT_REPLAY_MAX_ENTRIES");callbackBaseUrl=env.containsKey("HTTP_AGENT_CALLBACK_BASE_URL")?url(env.get("HTTP_AGENT_CALLBACK_BASE_URL"),insecure):null;
    String raw=env.get("AGENT_TRANSPORT_CONFIG");if(raw==null||raw.isBlank())return;JsonNode value;try{value=Json.parse(raw);}catch(Exception e){throw new AdapterError("HTTP_CONFIGURATION_INVALID",false,"AGENT_TRANSPORT_CONFIG must be valid JSON");}Json.requireObject(value,"AGENT_TRANSPORT_CONFIG");for(String agent:Json.keys(value)){if(agent.isEmpty())invalid("Agent name is empty");ObjectNode entry=Json.requireObject(value.get(agent),"Agent configuration");String kind=entry.path("kind").asText();Set<String> allowed=kind.equals("kafka")?Set.of("kind","delegationModes","connectionId"):Set.of("kind","submitUrl","outboundAuthentication","callbackAuthentication","requestTimeoutMs","maxResponseBytes","delegationModes","connectionId");only(entry,allowed);
      ObjectNode config=entry.deepCopy();ArrayNode modes=Json.array("opaque","observed");if(entry.hasNonNull("delegationModes")){JsonNode list=entry.get("delegationModes");if(!list.isArray()||list.isEmpty()||list.size()>2)invalid("Invalid delegation modes");Set<String> seen=new HashSet<>();for(JsonNode m:list)if(!m.isTextual()||!Set.of("opaque","observed").contains(m.asText())||!seen.add(m.asText()))invalid("Invalid delegation modes");modes=(ArrayNode)list.deepCopy();}config.set("delegationModes",modes);
      if(entry.has("connectionId")){JsonNode id=entry.get("connectionId");if(!id.isTextual()||id.asText().isEmpty()||id.asText().length()>255||!id.asText().matches("[A-Za-z0-9_.:-]+"))invalid("Invalid connectionId");}
      if(kind.equals("http")){config.put("submitUrl",url(required(entry.get("submitUrl"),"submitUrl"),insecure));ObjectNode outbound=Json.requireObject(entry.get("outboundAuthentication"),"outboundAuthentication");if(outbound.path("type").asText().equals("none")){only(outbound,Set.of("type"));}else if(outbound.path("type").asText().equals("bearer")){only(outbound,Set.of("type","tokenEnv"));String token=env.get(required(outbound.get("tokenEnv"),"tokenEnv"));if(token==null||token.isEmpty())invalid("Bearer token environment value is missing");config.put("bearer",token);}else invalid("Unsupported outbound authentication");ObjectNode callback=Json.requireObject(entry.get("callbackAuthentication"),"callbackAuthentication");only(callback,Set.of("keyId","secretEnv"));String keyId=required(callback.get("keyId"),"keyId");if(keyId.length()>255)invalid("Callback key ID exceeds durable bound");String secret=env.get(required(callback.get("secretEnv"),"secretEnv"));if(secret==null||secret.isEmpty())invalid("Callback secret environment value is missing");config.put("keyId",keyId);config.put("secret",secret);config.put("requestTimeoutMs",positiveNode(entry.get("requestTimeoutMs"),"requestTimeoutMs"));config.put("maxResponseBytes",positiveNode(entry.get("maxResponseBytes"),"maxResponseBytes"));if(callbackBaseUrl==null)invalid("HTTP_AGENT_CALLBACK_BASE_URL is required for HTTP agents");}else if(!kind.equals("kafka"))invalid("Unsupported transport kind");agents.put(agent,config);
    }
  }
  public ObjectNode forAgent(String agent){ObjectNode configured=agents.get(agent);if(configured!=null)return configured.deepCopy();if(agent.startsWith("conn__")||agent.startsWith("conn:")){String bearer=first("EXECUTOR_HOST_BEARER_TOKEN","HTTP_AGENT_BEARER_TOKEN"),secret=first("HTTP_AGENT_CALLBACK_SECRET","LOOPBACK_CALLBACK_SECRET");if(bearer==null||secret==null)throw new IllegalStateException("Local Runtime Bridge credentials missing");return Json.object("kind","http","submitUrl",Optional.ofNullable(first("LOCAL_EXECUTOR_HOST_URL","EXECUTOR_HOST_URL")).orElse("http://127.0.0.1:3002/v1/runs"),"bearer",bearer,"keyId","host-callback-v1","secret",secret,"requestTimeoutMs",300000,"maxResponseBytes",16777216,"delegationModes",Json.array("opaque","observed"));}return Json.object("kind","kafka","delegationModes",Json.array("opaque","observed"));}
  public HttpProfile httpForAgent(String agent){ObjectNode n=forAgent(agent);return !n.path("kind").asText().equals("http")?null:new HttpProfile(n.path("submitUrl").asText(),Json.text(n,"bearer"),n.path("keyId").asText(),n.path("secret").asText(),n.path("requestTimeoutMs").asInt(),n.path("maxResponseBytes").asInt());}
  public boolean hasKafkaAgents(){return agents.values().stream().anyMatch(n->n.path("kind").asText().equals("kafka"));}
  public boolean supportsObserved(String agent){for(JsonNode mode:forAgent(agent).path("delegationModes"))if(mode.asText().equals("observed"))return true;return false;}
  public ObjectNode descriptor(String agent){if(agent.isBlank()||agent.length()>255)throw new AdapterError("EXECUTOR_DESCRIPTOR_INVALID",false,"Invalid executor agent");ObjectNode config=forAgent(agent),profile=Json.object("kind",config.get("kind"));ObjectNode descriptor=Json.object("schemaVersion","1","executorId","agent:"+agent,"agent",agent,"kind",config.get("kind"),"capabilities",Json.object("cancel",false));if(config.path("kind").asText().equals("http")){ObjectNode http=Json.object("submitUrl",config.get("submitUrl"),"requestTimeoutMs",config.get("requestTimeoutMs"),"maxResponseBytes",config.get("maxResponseBytes"));descriptor.set("httpProfile",http);profile.set("httpProfile",http);}descriptor.put("configHash",Json.hash(profile));return descriptor;}
  public ObjectNode frozenDescriptor(JsonNode snapshot){if(snapshot==null||!snapshot.isObject())throw new AdapterError("EXECUTOR_SNAPSHOT_INVALID",false,"Executor snapshot must be an object");if(!snapshot.has("schemaVersion")){String agent=Json.text(snapshot,"agent");if(agent==null||agent.isEmpty())throw new AdapterError("EXECUTOR_SNAPSHOT_INVALID",false,"Invalid legacy executor snapshot");return descriptor(agent);}try{only(snapshot,Set.of("schemaVersion","executorId","agent","kind","configHash","capabilities","connection","requestedModelId","localProfile","httpProfile"));if(!snapshot.path("schemaVersion").asText().equals("1")||!Set.of("http","kafka").contains(snapshot.path("kind").asText()))invalid("Invalid executor version or kind");for(String key:List.of("agent","executorId"))if(required(snapshot.get(key),key).length()>255)invalid("Executor identifier exceeds bound");if(!snapshot.path("configHash").asText().matches("[0-9a-f]{64}"))invalid("Invalid executor hash");JsonNode caps=snapshot.get("capabilities");only(Json.requireObject(caps,"capabilities"),Set.of("cancel"));if(!caps.path("cancel").isBoolean())invalid("Invalid executor cancel capability");if(snapshot.path("kind").asText().equals("http")){JsonNode http=Json.requireObject(snapshot.get("httpProfile"),"httpProfile");only(http,Set.of("submitUrl","requestTimeoutMs","maxResponseBytes"));String submit=required(http.get("submitUrl"),"submitUrl");if(submit.length()>2048)invalid("HTTP profile URL exceeds bound");url(submit,true);positiveNode(http.get("requestTimeoutMs"),"requestTimeoutMs");positiveNode(http.get("maxResponseBytes"),"maxResponseBytes");}else if(snapshot.has("httpProfile"))invalid("Kafka executor cannot carry HTTP profile");if(snapshot.has("requestedModelId")){String model=required(snapshot.get("requestedModelId"),"requestedModelId");if(model.length()>256||!model.matches("[A-Za-z0-9][A-Za-z0-9._/\\-:@+]*"))invalid("Invalid model identifier");}return io.tenvyr.control.runtime.Executors.parseSnapshot(snapshot).deepCopy();}catch(RuntimeException e){throw new AdapterError("EXECUTOR_DESCRIPTOR_INVALID",false,"Frozen executor descriptor is invalid",0,e);}}
  public String callbackUrlFor(String agent){if(callbackBaseUrl==null)invalid("HTTP_AGENT_CALLBACK_BASE_URL is required for HTTP agents");try{URI uri=URI.create(callbackBaseUrl);String encoded=URLEncoder.encode(agent,java.nio.charset.StandardCharsets.UTF_8).replace("+","%20");return new URI(uri.getScheme(),uri.getRawAuthority(),uri.getPath().replaceFirst("/$","")+"/internal/agent-callbacks/http/"+encoded,uri.getQuery(),uri.getFragment()).toASCIIString().replace("%25","%");}catch(Exception e){throw new AdapterError("HTTP_CONFIGURATION_INVALID",false,"Invalid callback URL");}}
  public static String toTransportAgent(String id){if(id==null||id.isEmpty())return "default";if(id.startsWith("conn__"))return id;return "conn__"+id.replaceAll("[^A-Za-z0-9_.-]","_");}
  private String first(String a,String b){String s=env.get(a);return s!=null&&!s.isEmpty()?s:env.get(b);}
  private static String required(JsonNode n,String name){if(n==null||!n.isTextual()||n.asText().isBlank())invalid(name+" must be a non-empty string");return n.asText();}
  private static int positiveNode(JsonNode n,String name){if(n==null||!n.isIntegralNumber()||!n.canConvertToInt()||n.intValue()<=0)invalid(name+" must be a positive integer");return n.intValue();}
  private static int positive(String n,int fallback,String name){if(n==null)return fallback;try{double value=Double.parseDouble(n.trim());if(value>0&&value<=Integer.MAX_VALUE&&value==Math.floor(value))return (int)value;}catch(Exception ignored){}invalid(name+" must be a positive integer");return 0;}
  private static String url(String raw,boolean insecure){try{URI u=URI.create(raw);if(!u.isAbsolute()||u.getHost()==null||u.getUserInfo()!=null||(!"http".equals(u.getScheme())&&!"https".equals(u.getScheme()))||("http".equals(u.getScheme())&&!insecure))invalid("Agent URL requires HTTPS and cannot contain credentials");return u.toString();}catch(IllegalArgumentException e){throw new AdapterError("HTTP_CONFIGURATION_INVALID",false,"Invalid agent URL",0,e);}}
  private static void only(JsonNode n,Set<String> keys){for(String key:Json.keys(n))if(!keys.contains(key))invalid("Unsupported configuration field: "+key);}
  private static void invalid(String message){throw new AdapterError("HTTP_CONFIGURATION_INVALID",false,message);}
}
